const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString();
return {
  json: {
    since_iso: oneWeekAgo,
    now_iso: now.toISOString(),
    owner: $('Config Variables').first().json.GITHUB_OWNER,
    repo: $('Config Variables').first().json.GITHUB_REPO,
    lang: $('Config Variables').first().json.LANGUAGE || 'EN',
    webhook: $('Config Variables').first().json.WEBHOOK_URL,
    anthropic_key: $('Config Variables').first().json.ANTHROPIC_API_KEY
  }
};

const config = $('Compute Date Range').first().json;
const sinceDate = new Date(config.since_iso);

// 1. Process Commits
let commits = [];
try {
  const rawCommits = $('Fetch Commits').all();
  commits = rawCommits.map(c => {
    const j = c.json;
    return `- ${j.commit?.message?.split('\n')[0]} (by ${j.commit?.author?.name || 'unknown'})`;
  }).slice(0, 30);
} catch (e) {}

// 2. Process Closed Issues
let issues = [];
try {
  const rawIssues = $('Fetch Closed Issues').all();
  issues = rawIssues.filter(i => !i.json.pull_request).map(i => {
    return `- #${i.json.number}: ${i.json.title}`;
  }).slice(0, 20);
} catch (e) {}

// 3. Process Merged PRs
let prs = [];
try {
  const rawPrs = $('Fetch Merged PRs').all();
  prs = rawPrs.filter(p => {
    if (!p.json.merged_at) return false;
    return new Date(p.json.merged_at) >= sinceDate;
  }).map(p => {
    return `- PR #${p.json.number}: ${p.json.title} (merged by ${p.json.user?.login || 'contributor'})`;
  }).slice(0, 20);
} catch (e) {}

const languagePrompt = config.lang.toUpperCase() === 'FR'
  ? 'Rédige le résumé complet en français avec un ton professionnel et engageant.'
  : 'Write the complete summary in English with a professional, inspiring developer-friendly tone.';

const prompt = `You are an expert technical writer. Generate a comprehensive weekly developer narrative digest for the GitHub repository "${config.owner}/${config.repo}".\n\nLanguage Instruction: ${languagePrompt}\n\nActivity Data for the past 7 days:\n\n### COMMITS (${commits.length}):\n${commits.join('\n') || 'No direct commits.'}\n\n### CLOSED ISSUES (${issues.length}):\n${issues.join('\n') || 'No issues closed this week.'}\n\n### MERGED PULL REQUESTS (${prs.length}):\n${prs.join('\n') || 'No PRs merged this week.'}\n\nStructure your response in Markdown with:\n1. 🌟 **Executive Summary**: 2-3 paragraphs highlighting key achievements and velocity.\n2. 🚀 **Key Features & Improvements**: Highlights from merged PRs and commits.\n3. 🐛 **Bugs Resolved & Quality**: Critical fixes and closed issues.\n4. 🔮 **Outlook for Next Week**: Suggested focus areas based on recent trajectory.`;

return {
  json: {
    prompt: prompt,
    anthropic_key: config.anthropic_key,
    webhook_url: config.webhook,
    repo: `${config.owner}/${config.repo}`
  }
};

